// src/errors.ts
var PesapalError = class extends Error {
  constructor(message, code, type, status) {
    super(message);
    this.code = code;
    this.type = type;
    this.status = status;
    this.name = "PesapalError";
  }
};

// src/helpers/retries.ts
async function withRetries(fn, options = {}) {
  const {
    retries = 2,
    baseDelayMs = 500,
    maxDelayMs = 8e3,
    shouldRetry = defaultShouldRetry,
    onRetry
  } = options;
  let lastError;
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error;
      const retryable = shouldRetry(error);
      if (!retryable || attempt === retries) break;
      const delay = Math.min(baseDelayMs * 2 ** attempt, maxDelayMs);
      onRetry?.({
        attempt: attempt + 1,
        retries,
        error,
        delay
      });
      await sleep(delay);
    }
  }
  throw lastError;
}
function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}
function defaultShouldRetry(error) {
  const status = error?.response?.status;
  return status === 408 || status === 429 || status >= 500 || error.code === "ECONNRESET" || error.code === "ETIMEDOUT";
}

// src/auth.ts
var PesapalAuth = class {
  /**
   * Creates an instance of PesapalAuth.
   * @param config The configuration options.
   */
  constructor(config) {
    this.config = config;
    this.authPromise = null;
    this.baseURL = config.environment === "live" ? "https://pay.pesapal.com/v3" : "https://cybqa.pesapal.com/pesapalv3";
  }
  /**
   * Checks if the current token is valid and not close to expiry.
   * @returns True if the token is valid, false otherwise.
   */
  isTokenValid() {
    if (!this.token || !this.expiryDate) return false;
    const expiry = new Date(this.expiryDate).getTime();
    const now = Date.now();
    const buffer = 30 * 1e3;
    return expiry - now > buffer;
  }
  /**
   * Requests a fresh authentication token from Pesapal or returns a cached one.
   * Tokens typically expire after 5 minutes.
   * @returns A promise resolving to the authentication response.
   */
  async authenticate() {
    if (this.isTokenValid() && this.token && this.expiryDate) {
      return {
        token: this.token,
        expiryDate: this.expiryDate,
        status: "200",
        message: "Cached token",
        error: null
      };
    }
    if (this.authPromise) {
      return this.authPromise;
    }
    this.authPromise = withRetries(
      async () => {
        this.config.logger?.debug?.("Pesapal auth request started");
        const response = await fetch(`${this.baseURL}/api/Auth/RequestToken`, {
          method: "POST",
          headers: {
            Accept: "application/json",
            "Content-Type": "application/json"
          },
          body: JSON.stringify({
            consumer_key: this.config.consumerKey,
            consumer_secret: this.config.consumerSecret
          }),
          signal: AbortSignal.timeout(this.config.timeoutMs ?? 1e4)
        });
        if (!response.ok) {
          throw new Error(
            `HTTP error! status: ${response.status}, message: ${response.statusText}`
          );
        }
        const data = await response.json();
        this.token = data.token;
        this.expiryDate = data.expiryDate;
        this.config.logger?.info?.("Pesapal auth success", {
          expiryDate: data.expiryDate
        });
        return data;
      },
      {
        retries: this.config.retries,
        onRetry: ({ attempt, retries, error, delay }) => {
          this.config.logger?.warn?.("Retrying auth request", {
            attempt,
            retries,
            delay,
            message: error.message
          });
        }
      }
    ).finally(() => {
      this.authPromise = null;
    });
    return this.authPromise;
  }
};

// src/client.ts
var PesapalClient = class {
  /**
   * Creates an instance of PesapalClient.
   * @param config The configuration options.
   */
  constructor(config) {
    this.config = config;
    this.baseURL = config.environment === "live" ? "https://pay.pesapal.com/v3" : "https://cybqa.pesapal.com/pesapalv3";
    this.auth = new PesapalAuth(config);
  }
  /**
   * Makes an authenticated HTTP request to the Pesapal API V3.
   * @param method The HTTP method (GET, POST, etc.).
   * @param url The relative URL endpoint.
   * @param data Optional request payload.
   * @returns A promise that resolves to the response data.
   * @throws {PesapalError} If the request fails.
   */
  async request(method, url, data) {
    return withRetries(
      async () => {
        try {
          const authData = await this.auth.authenticate();
          this.config.logger?.debug?.("Pesapal request started", {
            method,
            url
          });
          const headers = {
            Accept: "application/json",
            Authorization: `Bearer ${authData.token}`
          };
          const requestOptions = {
            method,
            headers,
            signal: AbortSignal.timeout(this.config.timeoutMs ?? 1e4)
          };
          if (data !== void 0) {
            headers["Content-Type"] = "application/json";
            requestOptions.body = JSON.stringify(data);
          }
          const response = await fetch(`${this.baseURL}${url}`, requestOptions);
          if (!response.ok) {
            const errorData = await parseJsonResponse(response);
            throw new PesapalFetchError(
              `HTTP error! status: ${response.status}, message: ${response.statusText}`,
              response.status,
              errorData
            );
          }
          const responseData = await parseJsonResponse(response);
          this.config.logger?.debug?.("Pesapal request successful", {
            method,
            url,
            status: response.status
          });
          return responseData;
        } catch (err) {
          const pesapalError = this.normalizeError(err);
          this.config.logger?.error?.("Pesapal request failed", {
            method,
            url,
            status: pesapalError.status,
            code: pesapalError.code,
            message: pesapalError.message
          });
          throw pesapalError;
        }
      },
      {
        retries: this.config.retries,
        onRetry: ({ attempt, retries, error, delay }) => {
          this.config.logger?.warn?.("Retrying Pesapal request", {
            method,
            url,
            attempt,
            retries,
            delay,
            message: error.message
          });
        }
      }
    );
  }
  /**
   * Performs an authenticated GET request.
   */
  get(url) {
    return this.request("GET", url);
  }
  /**
   * Performs an authenticated POST request.
   */
  post(url, data) {
    return this.request("POST", url, data);
  }
  /**
   * Performs an authenticated PUT request.
   */
  put(url, data) {
    return this.request("PUT", url, data);
  }
  /**
   * Performs an authenticated DELETE request.
   */
  delete(url) {
    return this.request("DELETE", url);
  }
  /**
   * Normalizes errors into a consistent PesapalError format.
   */
  normalizeError(err) {
    if (err instanceof PesapalError) {
      return err;
    }
    if (err instanceof PesapalFetchError) {
      const error = err.errorData?.error;
      return new PesapalError(
        error?.message || err.message || "Pesapal request failed",
        error?.code,
        error?.type,
        err.statusCode
      );
    }
    return new PesapalError(err.message || "Pesapal request failed");
  }
};
var PesapalFetchError = class extends Error {
  constructor(message, statusCode, errorData) {
    super(message);
    this.statusCode = statusCode;
    this.errorData = errorData;
    this.name = "PesapalFetchError";
  }
};
async function parseJsonResponse(response) {
  if (response.status === 204) {
    return void 0;
  }
  try {
    return await response.json();
  } catch {
    return void 0;
  }
}

// src/helpers/validation.ts
function isValidEmailAddress(email) {
  if (email.length > 254) return false;
  const atIndex = email.indexOf("@");
  if (atIndex <= 0 || atIndex !== email.lastIndexOf("@")) return false;
  const localPart = email.slice(0, atIndex);
  const domain = email.slice(atIndex + 1);
  if (localPart.length > 64 || domain.length < 3 || domain.length > 253 || domain.startsWith(".") || domain.endsWith(".") || domain.includes("..")) {
    return false;
  }
  const dotIndex = domain.lastIndexOf(".");
  if (dotIndex <= 0 || dotIndex === domain.length - 1) return false;
  return !hasWhitespace(localPart) && !hasWhitespace(domain);
}
function hasWhitespace(value) {
  for (const char of value) {
    if (char === " " || char === "	" || char === "\r" || char === "\n") {
      return true;
    }
  }
  return false;
}

// src/orders.ts
var Orders = class {
  /**
   * Creates an instance of Orders.
   * @param client The authenticated Pesapal client.
   */
  constructor(client) {
    this.client = client;
  }
  /**
   * Submits a new payment order to Pesapal.
   * @param payload The order details (amount, currency, customer, etc.).
   * @returns A promise resolving to the order response containing the redirect URL.
   */
  async submitOrder(payload) {
    this.validateOrder(payload);
    return this.client.post(
      "/api/Transactions/SubmitOrderRequest",
      payload
    );
  }
  /**
   * Checks the status of a transaction.
   * @param orderTrackingId The tracking ID returned by Pesapal during order submission.
   * @returns A promise resolving to the transaction status details.
   */
  async getStatus(orderTrackingId) {
    if (!orderTrackingId) {
      throw new PesapalError(
        "Order tracking ID is required",
        "validation_error",
        "client",
        400
      );
    }
    return this.client.get(
      `/api/Transactions/GetTransactionStatus?orderTrackingId=${orderTrackingId}`
    );
  }
  /**
   * Client-side validation for order requests.
   */
  validateOrder(payload) {
    if (!payload.id)
      throw new PesapalError(
        "Merchant reference (id) is required",
        "validation_error",
        "client",
        400
      );
    if (!payload.amount || payload.amount <= 0)
      throw new PesapalError(
        "Amount must be greater than 0",
        "validation_error",
        "client",
        400
      );
    if (!payload.currency)
      throw new PesapalError(
        "Currency is required",
        "validation_error",
        "client",
        400
      );
    if (!payload.notification_id)
      throw new PesapalError(
        "Notification ID (ipn_id) is required",
        "validation_error",
        "client",
        400
      );
    if (!payload.callback_url)
      throw new PesapalError(
        "Callback URL is required",
        "validation_error",
        "client",
        400
      );
    if (payload.billing_address?.email_address) {
      if (!isValidEmailAddress(payload.billing_address.email_address)) {
        throw new PesapalError(
          "Invalid email address format",
          "validation_error",
          "client",
          400
        );
      }
    }
  }
};

// src/ipn.ts
var IPNResource = class {
  constructor(client) {
    this.client = client;
  }
  /**
   * Registers a publicly accessible IPN URL.
   *
   * The returned `ipn_id` should be used as `notification_id`
   * when submitting an order request.
   */
  registerIPNUrl(payload) {
    this.validateIPNRegistration(payload);
    return this.client.post(
      "/api/URLSetup/RegisterIPN",
      payload
    );
  }
  /**
   * Retrieves the list of registered IPN URLs for the current account.
   */
  getIPNList() {
    return this.client.get("/api/URLSetup/GetIpnList");
  }
  /**
   * Client-side validation for IPN registration requests.
   */
  validateIPNRegistration(payload) {
    if (!payload.url) {
      throw new PesapalError(
        "IPN URL is required",
        "validation_error",
        "client",
        400
      );
    }
    try {
      new URL(payload.url);
    } catch (e) {
      throw new PesapalError(
        "Invalid IPN URL format",
        "validation_error",
        "client",
        400
      );
    }
    if (!["GET", "POST"].includes(payload.ipn_notification_type)) {
      throw new PesapalError(
        "IPN notification type must be GET or POST",
        "validation_error",
        "client",
        400
      );
    }
  }
};

// src/recurring.ts
var SUBSCRIPTION_FREQUENCIES = [
  "DAILY",
  "WEEKLY",
  "MONTHLY",
  "YEARLY"
];
var RecurringPayments = class {
  /**
   * Creates an instance of RecurringPayments.
   * @param client The authenticated Pesapal client.
   */
  constructor(client) {
    this.client = client;
  }
  /**
   * Submits an order with recurring payment fields.
   *
   * Pesapal creates the subscription after the customer accepts recurring
   * payments on the checkout iframe.
   */
  async submitOrder(payload) {
    this.validateRecurringOrder(payload);
    return this.client.post(
      "/api/Transactions/SubmitOrderRequest",
      payload
    );
  }
  validateRecurringOrder(payload) {
    if (!payload.id)
      throw new PesapalError(
        "Merchant reference (id) is required",
        "validation_error",
        "client",
        400
      );
    if (!payload.amount || payload.amount <= 0)
      throw new PesapalError(
        "Amount must be greater than 0",
        "validation_error",
        "client",
        400
      );
    if (!payload.currency)
      throw new PesapalError(
        "Currency is required",
        "validation_error",
        "client",
        400
      );
    if (!payload.notification_id)
      throw new PesapalError(
        "Notification ID (ipn_id) is required",
        "validation_error",
        "client",
        400
      );
    if (!payload.callback_url)
      throw new PesapalError(
        "Callback URL is required",
        "validation_error",
        "client",
        400
      );
    if (!payload.account_number)
      throw new PesapalError(
        "Account number is required for recurring payments",
        "validation_error",
        "client",
        400
      );
    if (payload.billing_address?.email_address) {
      if (!isValidEmailAddress(payload.billing_address.email_address)) {
        throw new PesapalError(
          "Invalid email address format",
          "validation_error",
          "client",
          400
        );
      }
    }
    if (!payload.subscription_details) return;
    const dateRegex = /^\d{2}-\d{2}-\d{4}$/;
    if (!dateRegex.test(payload.subscription_details.start_date)) {
      throw new PesapalError(
        "Subscription start date must use dd-MM-yyyy format",
        "validation_error",
        "client",
        400
      );
    }
    if (!dateRegex.test(payload.subscription_details.end_date)) {
      throw new PesapalError(
        "Subscription end date must use dd-MM-yyyy format",
        "validation_error",
        "client",
        400
      );
    }
    if (!SUBSCRIPTION_FREQUENCIES.includes(payload.subscription_details.frequency)) {
      throw new PesapalError(
        "Subscription frequency must be DAILY, WEEKLY, MONTHLY, or YEARLY",
        "validation_error",
        "client",
        400
      );
    }
  }
};

// src/refunds.ts
var Refunds = class {
  /**
   * Creates an instance of Refunds.
   * @param client The authenticated Pesapal client.
   */
  constructor(client) {
    this.client = client;
  }
  /**
   * Requests a refund for a completed payment.
   *
   * Pesapal identifies the payment by the processor confirmation code returned
   * from the transaction status endpoint.
   */
  async requestRefund(payload) {
    this.validateRefund(payload);
    return this.client.post(
      "/api/Transactions/RefundRequest",
      payload
    );
  }
  validateRefund(payload) {
    if (!payload.confirmation_code)
      throw new PesapalError(
        "Confirmation code is required",
        "validation_error",
        "client",
        400
      );
    if (!payload.amount || payload.amount <= 0)
      throw new PesapalError(
        "Refund amount must be greater than 0",
        "validation_error",
        "client",
        400
      );
    if (!payload.username)
      throw new PesapalError(
        "Username is required",
        "validation_error",
        "client",
        400
      );
    if (!payload.remarks)
      throw new PesapalError(
        "Refund remarks are required",
        "validation_error",
        "client",
        400
      );
  }
};

// src/cancellations.ts
var OrderCancellations = class {
  /**
   * Creates an instance of OrderCancellations.
   * @param client The authenticated Pesapal client.
   */
  constructor(client) {
    this.client = client;
  }
  /**
   * Cancels a pending or failed order by its Pesapal order tracking ID.
   */
  async cancelOrder(payload) {
    this.validateCancellation(payload);
    return this.client.post(
      "/api/Transactions/CancelOrder",
      payload
    );
  }
  validateCancellation(payload) {
    if (!payload.order_tracking_id)
      throw new PesapalError(
        "Order tracking ID is required",
        "validation_error",
        "client",
        400
      );
  }
};

// src/helpers/ipn.ts
import { createHmac } from "crypto";
function verifyIPNSignature(signature, rawBody, consumerSecret) {
  const hmac = createHmac("sha256", consumerSecret);
  const expectedSignature = hmac.update(rawBody).digest("hex");
  return signature === expectedSignature;
}
function parseIPN(body) {
  const data = typeof body === "string" ? JSON.parse(body) : body;
  return {
    OrderTrackingId: data.OrderTrackingId || data.order_tracking_id,
    OrderMerchantReference: data.OrderMerchantReference || data.order_merchant_reference,
    OrderNotificationType: data.OrderNotificationType || data.order_notification_type
  };
}

// src/index.ts
var Pesapal = class {
  /**
   * Creates an instance of the Pesapal SDK.
   * @param config The configuration options for the SDK.
   */
  constructor(config) {
    this.client = new PesapalClient(config);
    this.orders = new Orders(this.client);
    this.ipn = new IPNResource(this.client);
    this.recurring = new RecurringPayments(this.client);
    this.refunds = new Refunds(this.client);
    this.cancellations = new OrderCancellations(this.client);
  }
};
export {
  OrderCancellations,
  Pesapal,
  PesapalError,
  RecurringPayments,
  Refunds,
  parseIPN,
  verifyIPNSignature
};
